BEGIN;

-- Guest credentials are generated by the browser; only their digest is stored.
ALTER TABLE tarot_users ALTER COLUMN wechat_app_id DROP NOT NULL;
ALTER TABLE tarot_users ALTER COLUMN wechat_open_id DROP NOT NULL;
ALTER TABLE tarot_users ADD COLUMN IF NOT EXISTS guest_token_hash text;
CREATE UNIQUE INDEX IF NOT EXISTS tarot_users_guest_token_idx ON tarot_users (guest_token_hash);

COMMIT;
